#pragma once
// Offline identification and candidate screening. No ROS publisher or actuator API.
#include <algorithm>
#include <array>
#include <cmath>
#include <fstream>
#include <limits>
#include <numeric>
#include <optional>
#include <sstream>
#include <stdexcept>
