namespace cefiro::gui::autotune {
constexpr double pi=3.14159265358979323846, rad=pi/180., dt=.005;
inline double wrap(double x){return std::atan2(std::sin(x),std::cos(x));}
struct Model {double j=.03378,a=24.3018157347,b=.6177391586,cw=26.0718091181,ccw=25.4276454707,offset=6.5*rad,delay=.16,maxcw=909,maxccw=969; double train=.2176631965,test=.3181567076; int n=432,ntest=109; bool imported=false,fmu=false,diagnostic=false,voltage_normalized=false; double voltage_ref=12.,voltage_min=0.,voltage_max=0.;};
struct Row{double t{},angle{},rate{},pitch{},u{},v{};bool valid{};double voltage=0.;bool voltage_valid=false;double power=0.;bool power_valid=false;double power_time=0.;};
struct Run{std::vector<Row> rows;bool fmu{},diagnostic{};};
inline std::vector<std::string> split(const std::string& line){std::vector<std::string> r;std::string s;bool quoted=false;for(size_t i=0;i<line.size();++i){char c=line[i];if(c=='"'){if(quoted&&i+1<line.size()&&line[i+1]=='"'){s+='"';++i;}else quoted=!quoted;}else if(c==','&&!quoted){r.push_back(s);s.clear();}else if(c!='\r')s+=c;}r.push_back(s);return r;}
inline double num(const std::string& s){try{size_t n=0;double x=std::stod(s,&n);if(n==s.size()&&std::isfinite(x))return x;}catch(...){}return std::numeric_limits<double>::quiet_NaN();}
inline Run read(const std::string& path){std::ifstream f(path);std::string line;if(!std::getline(f,line))throw std::runtime_error("Cannot read CSV");const auto h=split(line);auto ix=[&](const std::string& key){auto p=std::find(h.begin(),h.end(),key);return p==h.end()?-1:int(p-h.begin());};for(auto key:{"ros_time_s","roll_deg","p_deg_s","pitch_deg","plant","quaternion_valid","motor_map_revision"})if(ix(key)<0)throw std::runtime_error(std::string("Missing column: ")+key);std::vector<std::vector<std::string>> raw;while(std::getline(f,line)){if(raw.size()>=250000)throw std::runtime_error("CSV exceeds 250000 rows");raw.push_back(split(line));}auto get=[&](const auto& r,const std::string& k){const int i=ix(k);return i>=0&&size_t(i)<r.size()?r[size_t(i)]:std::string{};};int fm=0,host=0,ahrs=0,diag=0;for(auto& r:raw){fm+=get(r,"fmu_dshot_valid")=="1";host+=get(r,"host_dshot_valid")=="1";ahrs+=get(r,"quaternion_valid")=="1";diag+=get(r,"gui_fusion_valid")=="1";}Run result;result.diagnostic=ahrs<100&&diag>=100;result.fmu=fm>=50&&fm>=host/2;const std::string prefix=result.fmu?"fmu":"host";if(ix(prefix+"_dshot_valid")<0)throw std::runtime_error("Missing DShot validity");for(int i=1;i<=4;++i)if(ix("dshot_"+prefix+"_m"+std::to_string(i))<0)throw std::runtime_error("Missing motor columns");std::optional<double> first_tick; double previous_tick=-1.;for(auto& r:raw){auto val=[&](const std::string& k){return num(get(r,k));};Row a{val("ros_time_s"),val(result.diagnostic?"gui_roll_deg":"roll_deg")*rad,val("p_deg_s")*rad,val(result.diagnostic?"gui_pitch_deg":"pitch_deg")*rad};std::array<double,4> d{};for(int i=0;i<4;++i)d[i]=val("dshot_"+prefix+"_m"+std::to_string(i+1));a.valid=get(r,"plant")=="REAL"&&get(r,result.diagnostic?"gui_fusion_valid":"quaternion_valid")=="1"&&get(r,prefix+"_dshot_valid")=="1"&&std::isfinite(a.t)&&std::isfinite(a.angle)&&std::isfinite(a.rate)&&std::isfinite(a.pitch)&&std::abs(a.pitch)<.35&&get(r,"motor_map_revision")=="3"&&std::abs(d[0]-d[3])<=2&&std::abs(d[1]-d[2])<=2;for(double x:d)a.valid=a.valid&&std::isfinite(x)&&x>=0&&x<=2047&&(x==0||x>=48);if(!result.fmu){double age=val("host_dshot_age_s");a.valid=a.valid&&std::isfinite(age)&&age>=0&&age<=.2;}a.u=(d[0]+d[3])/2000.;a.v=(d[1]+d[2])/2000.;/* In automatic trials the inactive pair is held at protocol idle 48, not zero. Preserve its measured contribution in the regression. */ a.valid=a.valid&&(a.u<=.048||a.v<=.048);if(result.fmu){
    const double tick=val("fmu_sample_ms");
    if(get(r,"fmu_dshot_valid")=="1" && std::isfinite(tick)&&tick>=0&&tick<=4294967295.&&std::floor(tick)==tick){
      if(!first_tick)first_tick=tick;
      if(tick<=previous_tick)throw std::runtime_error("MCU timestamps repeat or reset; split recording or remove duplicate samples");
      previous_tick=tick;a.t=(tick-*first_tick)*.001;
    }else {a.valid=false;a.t=std::numeric_limits<double>::quiet_NaN();}
  }
  const double v=val("battery_voltage_v"),age=val("esc_power_age_s"),ptick=val("esc_power_sample_ms"),itick=val("fmu_sample_ms");
  a.voltage_valid=result.fmu&&get(r,"esc_power_tick_valid")=="1"&&get(r,"battery_valid")=="1"&&std::isfinite(v)&&v>=8.&&v<=16.&&std::isfinite(age)&&age>=0&&age<=.35&&std::isfinite(ptick)&&ptick>=0&&ptick<=4294967295.&&std::floor(ptick)==ptick&&std::isfinite(itick)&&itick>=ptick&&itick<=4294967295.&&std::abs((itick-ptick)*.001-age)<=.002;
  if(a.voltage_valid){a.voltage=v;a.power_time=ptick*.001;const double i=val("esc_current_a");a.power_valid=get(r,"esc_current_valid")=="1"&&std::isfinite(i)&&i>=0.;if(a.power_valid)a.power=v*i;}
  if (!result.rows.empty() && a.t <= result.rows.back().t) {
    a.valid = false;
  }
  result.rows.push_back(a);
 }
 if (std::none_of(result.rows.begin(),result.rows.end(),[](const Row& r){return r.valid;})) throw std::runtime_error("No valid Rev3 motor-pair samples; do not reuse old map CSVs");
 if (result.rows.size() < 100) {
   throw std::runtime_error("Not enough samples");
 }
 return result;
}
struct PowerSummary{int samples{},voltageSamples{};double minV=0.,maxV=0.,peakW=0.,energyJ=0.,coveredS=0.;};
inline PowerSummary powerSummary(const Run& run){PowerSummary s;double last=-1.,lastV=-1.,lastW=0.;bool previous=false;for(const auto& r:run.rows){if(r.voltage_valid&&r.power_time!=lastV){if(s.voltageSamples==0)s.minV=r.voltage;else s.minV=std::min(s.minV,r.voltage);s.maxV=std::max(s.maxV,r.voltage);++s.voltageSamples;lastV=r.power_time;}if(!r.voltage_valid||!r.power_valid){previous=false;continue;}if(r.power_time==last)continue;s.peakW=std::max(s.peakW,r.power);++s.samples;const double h=r.power_time-last;if(previous&&h>0&&h<=.35){s.energyJ+=.5*(lastW+r.power)*h;s.coveredS+=h;}last=r.power_time;lastW=r.power;previous=true;}return s;}
struct Window{std::array<double,4> x{};double y{};bool test{};};
inline std::vector<Window> windows(const std::vector<Run>& runs,double delay,double offset,bool voltage=false){std::vector<Window> out;for(const auto& run:runs){const auto& r=run.rows;for(size_t k=0;k+10<r.size();k+=10){size_t e=k+1;while(e<r.size()&&r[e].t-r[k].t<.36)++e;if(e>=r.size()||!std::isfinite(r[k].t)||!std::isfinite(r[e].t)||r[e].t-r[k].t<.36||r[e].t-r[k].t>.55)continue;Window w;w.y=r[e].rate-r[k].rate;w.test=k>=r.size()*7/10;if(!w.test&&e>=r.size()*7/10)continue;bool good=r[e].valid;for(size_t i=k;good&&i<e;++i){size_t q=i;while(q>0&&r[q].t>r[i].t-delay)--q;const double h=r[i+1].t-r[i].t;if(!r[i].valid||!r[q].valid||!std::isfinite(h)||h<=0||h>.12||r[q].t>r[i].t-delay+.001||r[i].t-delay-r[q].t>.12){good=false;break;}w.x[0]+=std::sin(r[i].angle-offset)*h;w.x[1]-=r[i].rate*h;double factor=1.;if(voltage&&(r[q].u!=0||r[q].v!=0)){if(!r[q].voltage_valid){good=false;break;}factor=std::pow(r[q].voltage/12.,2);}
      w.x[2]+=r[q].u*r[q].u*h*factor;w.x[3]-=r[q].v*r[q].v*h*factor;}if(good)out.push_back(w);}}return out;}
inline std::optional<std::array<double,4>> regress(const std::vector<Window>& w){double a[4][5]{};int n=0;for(auto& r:w)if(!r.test){++n;for(int i=0;i<4;++i)for(int j=0;j<5;++j)a[i][j]+=r.x[i]*(j==4?r.y:r.x[j]);}if(n<35)return {};for(int i=0;i<4;++i){int p=i;for(int j=i+1;j<4;++j)if(std::abs(a[j][i])>std::abs(a[p][i]))p=j;if(std::abs(a[p][i])<1e-7)return {};for(int j=0;j<5;++j)std::swap(a[i][j],a[p][j]);double d=a[i][i];for(auto& x:a[i])x/=d;for(int j=0;j<4;++j)if(j!=i){double c=a[j][i];for(int k=0;k<5;++k)a[j][k]-=c*a[i][k];}}return std::array<double,4>{a[0][4],a[1][4],a[2][4],a[3][4]};}
inline Model fit(const std::vector<Run>& runs,double offset=6.5*rad,bool voltage=false){if(runs.empty())throw std::runtime_error("Select real experiment CSV files");Model best;best.train=1e99;best.maxcw=best.maxccw=0;bool source=runs.front().fmu;if(!source||runs.front().diagnostic)throw std::runtime_error("Rev3 torque identification requires confirmed FMU setpoints and FMU AHRS; host-only or GUI fusion data is diagnostic only");double cw=0,ccw=0;for(const auto& run:runs){if(run.fmu!=source||run.diagnostic!=runs.front().diagnostic)throw std::runtime_error("Do not mix command or orientation sources between files");for(const auto& r:run.rows)if(r.valid){cw=std::max(cw,r.u*1000);ccw=std::max(ccw,r.v*1000);}}double vmin=1e9,vmax=0.;int powered=0,withVoltage=0;
 for(const auto& run:runs)for(const auto& row:run.rows)if(row.valid&&(row.u!=0||row.v!=0)){++powered;if(row.voltage_valid){++withVoltage;vmin=std::min(vmin,row.voltage);vmax=std::max(vmax,row.voltage);}}
 if(voltage&&(!source||powered<100||withVoltage<powered*.9||vmax-vmin<.15))throw std::runtime_error("Voltage model needs FMU setpoints, >=90% valid powered voltage samples and >=0.15 V observed span");
 if (cw < 100 || ccw < 100) {
   std::ostringstream details;
   details << "Both Roll motor pairs must be excited in the records. Accepted maximum CW (M1/M4): " << cw
           << "; CCW (M2/M3): " << ccw << ". Select both CSVs together. Source: " << (source?"FMU SETPOINT":"HOST REQUEST");
   for(const auto& run:runs){
     int valid=0;double u=0.,v=0.;
     for(const auto& row:run.rows)if(row.valid){++valid;u=std::max(u,row.u*1000.);v=std::max(v,row.v*1000.);}
     details << "\nRecord: " << valid << "/" << run.rows.size() << " accepted; CW=" << u << "; CCW=" << v;
   }
   throw std::runtime_error(details.str());
 }
 for(int d=0;d<=8;++d){double delay=.04*d;auto w=windows(runs,delay,offset,voltage);auto k=regress(w);if(!k||(*k)[0]<=0||(*k)[0]>100||(*k)[1]<0||(*k)[1]>20||(*k)[2]<=0||(*k)[2]>200||(*k)[3]<=0||(*k)[3]>200)continue;double s[2]{};int n[2]{};for(auto& r:w){double e=r.y-std::inner_product(r.x.begin(),r.x.end(),k->begin(),0.);s[r.test]+=e*e;++n[r.test];}if(n[0]<35||n[1]<15)continue;double rmse=std::sqrt(s[0]/n[0]);if(rmse<best.train){best.a=(*k)[0];best.b=(*k)[1];best.cw=(*k)[2];best.ccw=(*k)[3];best.offset=offset;best.delay=delay;best.train=rmse;best.test=std::sqrt(s[1]/n[1]);best.n=n[0];best.ntest=n[1];best.maxcw=cw;best.maxccw=ccw;best.imported=true;best.fmu=source;best.diagnostic=runs.front().diagnostic;best.voltage_normalized=voltage;best.voltage_min=withVoltage?vmin:0.;best.voltage_max=vmax;}}if(!best.imported)throw std::runtime_error("No identifiable positive model with holdout; check data coverage and valid AHRS");return best;}
struct Gain{double kp{},kd{},r{};bool robust{};};
// ZOH sampled linear model with a delayed input queue. Schur recursion tests
// strict unit-disc stability of z^d det(zI-Ad)+K adj(zI-Ad) Bd.
inline bool stable(double a,double b,double authority,double j,const Gain& k,int delay){const double c=std::sqrt(b*b/4+a),e=std::exp(-b*dt/2),ch=std::cosh(c*dt),sh=std::sinh(c*dt)/c;const double A=e*(ch+b*sh/2),B=e*sh,C=e*a*sh,D=e*(ch-b*sh/2);const double g=authority/j, U=(A-1)*g/a,V=C*g/a;std::vector<long double> p(size_t(delay)+3);p[0]=1;p[1]=-(A+D);p[2]=A*D-B*C;p[size_t(delay)+1]+=k.kp*U+k.kd*V;p[size_t(delay)+2]+=k.kp*(B*V-D*U)+k.kd*(C*U-A*V);while(p.size()>1){long double first=p.front(),last=p.back();if(!std::isfinite(first)||!std::isfinite(last)||std::abs(last)>=std::abs(first)*(1-1e-12L))return false;std::vector<long double> q(p.size()-1);for(size_t i=0;i<q.size();++i)q[i]=p[i]-last/first*p[p.size()-1-i];long double norm=std::abs(q[0]);if(norm<1e-24L)return false;for(auto& x:q)x/=norm;p=std::move(q);}return true;}
inline std::vector<Gain> lqr(const Model& m){std::vector<Gain> out;double g=m.j*m.a*std::cos(m.offset),b=m.j*m.b;for(double r:{30.,100.,300.,1000.,3000.,10000.,100000.}){Gain k;k.r=r;k.kp=g+std::sqrt(g*g+1/std::pow(5*rad,2)/r);k.kd=-b+std::sqrt(b*b+2*m.j*k.kp+1/std::pow(30*rad,2)/r);k.robust=true;for(double a:{.9,1.,1.1})for(double d:{.8,1.,1.2})for(double u:{.9,1.,1.1})for(int n=0;n<=int(std::ceil((m.delay+.01)/dt));++n)if(k.robust&&!stable(m.a*std::cos(m.offset)*a,m.b*d,u,m.j,k,n))k.robust=false;out.push_back(k);}return out;}
struct Candidate{std::string strategy;double kp{},kd{},duration{},energy{},cost{},capture{-1},maxRate{},peak{},sat{};int direction{1},pass{},cases{};Gain gain;};
struct Point{double t,phi,ref,p,torque,applied,energy;};
struct Outcome{double cost{},capture{-1},maxRate{},peak{},sat{};bool success{};};
inline Outcome simulate(const Model& m,const Candidate& c,double scale,double damping,double delay,double perturb,std::vector<Point>* trace=nullptr){const double kg=m.j*m.a, b=m.j*m.b*damping;const double vf=m.voltage_normalized?std::pow(m.voltage_min/m.voltage_ref,2):1.;const double positive=m.j*m.cw*std::pow(m.maxcw/1000,2)*scale*vf, negative=m.j*m.ccw*std::pow(m.maxccw/1000,2)*scale*vf;const double start=m.offset-pi+perturb, target=c.direction>0?0.:-2*pi;double phi=start,p=0,dwell=0,hold=0;Outcome o;std::vector<double> queue(size_t(std::max(1,int(std::round(delay/dt)))),0.);size_t q=0;bool captured=false,escaped=false;double T=c.strategy=="ENERGY"?25:c.duration+6;for(int i=0;i<int(T/dt);++i){double t=i*dt,z=std::min(1.,t/c.duration),z2=z*z,z3=z*z2,z4=z*z3,z5=z*z4,delta=target-start;double ref=start+delta*(10*z3-15*z4+6*z5),r=delta*(30*z2-60*z3+30*z4)/c.duration,acc=delta*(60*z-180*z2+120*z3)/(c.duration*c.duration);double err=wrap(phi-target),E=.5*m.j*p*p+kg*std::cos(phi-m.offset),desired=kg*std::cos(m.offset);if(!captured&&std::abs(err)<9*rad&&std::abs(p)<25*rad&&(c.strategy=="ENERGY"||z>=1)){dwell+=dt;if(dwell>=.55){captured=true;o.capture=t;}}else if(!captured)dwell=0;double raw;if(captured){raw=kg*std::sin(m.offset)-c.gain.kp*err-c.gain.kd*p;if(std::abs(err)>.60||std::abs(p)>1.75)escaped=true;hold+=dt;}else if(c.strategy=="ENERGY"){raw=b*p+c.energy*(desired-E)*p;if(std::abs(p)<.12&&std::abs(err)>1.0)raw+=c.direction*.12;ref=target;}else raw=m.j*acc+b*r-kg*std::sin(phi-m.offset)-c.kp*(phi-ref)-c.kd*(p-r);double command=std::clamp(raw,-std::min(negative,1.1),std::min(positive,1.1));double applied=queue[q];queue[q]=command;q=(q+1)%queue.size();if(delay<dt*.5)applied=command;double a=(kg*std::sin(phi-m.offset)-b*p+applied)/m.j;p+=dt*a;phi+=dt*p;o.maxRate=std::max(o.maxRate,std::abs(p));o.peak=std::max(o.peak,std::abs(raw));o.sat+=std::abs(raw-command)>1e-8?dt:0.;o.cost+=dt*(2*wrap(phi-target)*wrap(phi-target)+.05*p*p+.5*command*command+3*std::abs(raw-command));if(trace&&i%8==0)trace->push_back({t,phi,ref,p,raw,applied,E});if(!std::isfinite(phi)||std::abs(phi-start)>4*pi||std::abs(p)>120*rad){escaped=true;break;}if(captured&&hold>=3.)break;}o.success=captured&&!escaped&&hold>=3.&&std::abs(wrap(phi-target))<5*rad&&std::abs(p)<15*rad;o.cost+=o.success?o.capture:1000;return o;}
inline std::vector<Candidate> optimize(const Model& m){auto gains=lqr(m);std::vector<Candidate> out;auto evaluate=[&](Candidate c){for(double scale:{.9,1.,1.1})for(double d:{.8,1.2})for(double delay:{m.delay,m.delay+.01}){auto o=simulate(m,c,scale,d,delay,scale<1?.02:-.02);c.cost+=o.cost;c.capture=std::max(c.capture,o.capture);c.maxRate=std::max(c.maxRate,o.maxRate);c.peak=std::max(c.peak,o.peak);c.sat=std::max(c.sat,o.sat);c.pass+=o.success;++c.cases;}c.cost/=c.cases;out.push_back(c);};for(const auto& g:gains)for(int dir:{1,-1}){for(double kp:{.6,1.1,1.6})for(double kd:{.3,.5,.8})for(double duration:{8.,12.,16.}){Candidate c;c.strategy="QUINTIC_PD";c.kp=kp;c.kd=kd;c.duration=duration;c.direction=dir;c.gain=g;evaluate(c);}for(double k:{.1,.25,.5,1.}){Candidate c;c.strategy="ENERGY";c.energy=k;c.duration=12;c.direction=dir;c.gain=g;evaluate(c);}}std::sort(out.begin(),out.end(),[](const auto& a,const auto& b){if(a.gain.robust!=b.gain.robust)return a.gain.robust>b.gain.robust;if(a.pass!=b.pass)return a.pass>b.pass;return a.cost<b.cost;});return out;}
}
